};

const $ = (id) => document.getElementById(id);

async function api(path, options) {
  const res = await fetch(path, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    throw new Error(`Resposta inválida de ${path} (HTTP ${res.status})`);
  }
  if (!res.ok) {
    throw new Error((data && data.error) || `HTTP ${res.status} em ${path}`);
  }
  return data;
}

async function apiOptional(path, fallback) {
  try {
    return await api(path);
  } catch (err) {
    console.warn(err);
    return fallback;
  }
}

function alertKey(a) {
  return `${a.ts}|${a.rule_id}|${a.process?.pid}|${a.process?.name}`;
}

function renderStats(stats) {
  $("statTotal").textContent = stats.total_alerts ?? 0;
  $("statCritical").textContent = stats.by_severity?.critical ?? 0;
  $("statHigh").textContent = stats.by_severity?.high ?? 0;
  $("statRules").textContent = stats.rules ?? 0;
  $("statMonitor").textContent = stats.monitor_running ? "on" : "off";
  state.monitor = !!stats.monitor_running;

  const pill = $("livePill");
  const btn = $("btnMonitor");
  if (state.monitor) {
    pill.classList.add("on");
    pill.textContent = "monitor on";
    btn.textContent = "Parar monitor";
    btn.classList.add("danger");
  } else {
    pill.classList.remove("on");
    pill.textContent = "ao vivo";
    btn.textContent = "Iniciar monitor";
    btn.classList.remove("danger");
  }
}

function setLayoutMode() {
  const layout = $("mainLayout");
  const auditSelect = $("auditSource");
  const search = $("search");
  const severity = $("severity");

  const coverageMode = state.tab === "coverage";
