from eagle.runner import AgentRunner, RuntimePaths, default_paths


class ConsoleState:
    def __init__(self, paths: RuntimePaths) -> None:
        self.paths = paths
        self._lock = threading.Lock()
        self._monitor_stop = threading.Event()
        self._monitor_thread: threading.Thread | None = None
        self.monitor_running = False
        self.last_scan_alerts = 0
        self.last_error: str | None = None

    def read_alerts(self, limit: int = 200) -> list[dict[str, Any]]:
        path = self.paths.alerts
        if not path.exists():
            return []
        lines = path.read_text(encoding="utf-8").strip().splitlines()
        out: list[dict[str, Any]] = []
        for line in lines[-limit:]:
            try:
                out.append(json.loads(line))
            except json.JSONDecodeError:
                continue
        out.reverse()
        return out

    def stats(self) -> dict[str, Any]:
        alerts = self.read_alerts(limit=5000)
        by_sev = Counter((a.get("severity") or "unknown").lower() for a in alerts)
        rules = 0
        if self.paths.rules.exists():
            try:
                import yaml

                data = yaml.safe_load(self.paths.rules.read_text(encoding="utf-8")) or {}
                rules = len(data.get("rules") or [])
            except Exception:
                rules = 0
        quar = 0
        if self.paths.quarantine.exists():
            quar = sum(1 for p in self.paths.quarantine.iterdir() if p.is_file())
        return {
            "total_alerts": len(alerts),
            "by_severity": dict(by_sev),
            "rules": rules,
            "quarantine_files": quar,
            "monitor_running": self.monitor_running,
            "last_scan_alerts": self.last_scan_alerts,
            "last_error": self.last_error,
            "alerts_path": str(self.paths.alerts),
        }

    def scan_once(self, evaluate_all: bool = True) -> dict[str, Any]:
        with self._lock:
            try:
                runner = AgentRunner(
                    paths=self.paths,
                    evaluate_all=evaluate_all,
                    enforce=False,
                    quiet=True,
                )
                n = runner.pass_once()
                self.last_scan_alerts = n
                self.last_error = None
                return {"ok": True, "alerts": n}
            except Exception as exc:
                self.last_error = str(exc)
                return {"ok": False, "error": str(exc)}

    def start_monitor(self, interval: float = 3.0) -> dict[str, Any]:
        with self._lock:
            if self.monitor_running:
                return {"ok": True, "monitor_running": True}
            self._monitor_stop.clear()

            def loop() -> None:
                runner = AgentRunner(
                    paths=self.paths,
                    interval=interval,
                    enforce=False,
                    evaluate_all=False,
                    stop_check=self._monitor_stop.is_set,
                    quiet=True,
                )
                self.monitor_running = True
                try:
                    runner.run_forever()
                except Exception as exc:
                    self.last_error = str(exc)
                finally:
                    self.monitor_running = False

            self._monitor_thread = threading.Thread(target=loop, name="eagle-monitor", daemon=True)
            self._monitor_thread.start()
            return {"ok": True, "monitor_running": True}

    def stop_monitor(self) -> dict[str, Any]:
        self._monitor_stop.set()
        thread = self._monitor_thread
        if thread and thread.is_alive():
            thread.join(timeout=5)
        self.monitor_running = False
        return {"ok": True, "monitor_running": False}

    def quarantine_list(self) -> list[str]:
        if not self.paths.quarantine.exists():
            return []
        return sorted(p.name for p in self.paths.quarantine.iterdir() if p.is_file())

    def rules_summary(self) -> list[dict[str, Any]]:
        if not self.paths.rules.exists():
            return []
        import yaml

        data = yaml.safe_load(self.paths.rules.read_text(encoding="utf-8")) or {}
        return [
            {
                "id": r.get("id"),
                "name": r.get("name"),
                "severity": r.get("severity"),
                "action": r.get("action"),
            }
            for r in (data.get("rules") or [])
        ]

    def _known_rule_ids(self) -> set[str]:
        return {str(r.get("id")) for r in self.rules_summary() if r.get("id")}

    def coverage_summary(self) -> dict[str, Any]:
        if not self.paths.coverage.exists():
            return {"title": "Cobertura", "note": "coverage.yaml ausente", "pillars": []}
        alerts = self.read_alerts(limit=5000)
        hits = Counter((a.get("rule_id") or "") for a in alerts)
        raw = load_coverage(self.paths.coverage)
        return enrich_coverage(raw, self._known_rule_ids(), hits)

    def audit_logs(self, source: str = "alerts", limit: int = 100) -> dict[str, Any]:
        mapping = {
            "alerts": self.paths.alerts,
            "telemetry": self.paths.telemetry,
            "service": self.paths.logs / "service.log",
        }
        path = mapping.get(source, self.paths.alerts)
        return {
            "source": source,
            "path": str(path),
            "entries": read_recent_log_lines(path, limit=limit),
        }


