from eagle.models import ProcessEvent
from eagle.sensor import Sensor


class Correlator:
    """Enriquece eventos com tags comportamentais simples."""

    def __init__(self, sensor: Sensor) -> None:
        self.sensor = sensor

    def enrich(self, events: list[ProcessEvent]) -> list[ProcessEvent]:
        mass = self.sensor.mass_write_pids()
        for event in events:
            tags = set(event.tags)
            if event.pid in mass:
                tags.add("mass_file_write")
            # Office → shell já é coberto por regra; tag auxiliar
            if event.parent_name in {
                "winword.exe",
                "excel.exe",
                "powerpnt.exe",
                "outlook.exe",
            } and event.name in {
                "cmd.exe",
                "powershell.exe",
                "pwsh.exe",
                "wscript.exe",
                "cscript.exe",
            }:
                tags.add("office_child_shell")
            event.tags = sorted(tags)
        return events

