    alert_rule_counts: Counter[str] | None = None,
) -> dict[str, Any]:
    alert_rule_counts = alert_rule_counts or Counter()
    pillars_out: list[dict[str, Any]] = []

    for pillar in coverage.get("pillars") or []:
        items_out: list[dict[str, Any]] = []
        counts = Counter()
        for item in pillar.get("items") or []:
            rules = list(item.get("rules") or [])
            linked = [r for r in rules if r in known_rule_ids]
            missing = [r for r in rules if r not in known_rule_ids]
            hits = sum(alert_rule_counts.get(r, 0) for r in linked)
            status = item.get("status", "planned")
            counts[status] += 1
            items_out.append(
                {
                    "id": item.get("id"),
                    "name": item.get("name"),
                    "mitre": item.get("mitre"),
                    "status": status,
                    "status_label": STATUS_LABEL.get(status, status),
                    "contempla": True,
                    "rules": linked,
                    "rules_missing": missing,
                    "alert_hits": hits,
                    "sources": item.get("sources") or [],
                }
            )

        pillars_out.append(
            {
                "id": pillar.get("id"),
                "name": pillar.get("name"),
                "contempla": bool(pillar.get("contempla", True)),
                "items": items_out,
                "summary": {
                    "total": len(items_out),
                    "by_status": dict(counts),
                    "with_rules": sum(1 for i in items_out if i["rules"]),
                    "alert_hits": sum(i["alert_hits"] for i in items_out),
                },
            }
        )

    return {
        "title": coverage.get("title", "Monitoramento contratado"),
        "note": (coverage.get("note") or "").strip(),
        "pillars": pillars_out,
    }


def read_recent_log_lines(path: Path, limit: int = 100) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    lines = path.read_text(encoding="utf-8", errors="replace").strip().splitlines()
    out: list[dict[str, Any]] = []
    for line in lines[-limit:]:
        line = line.strip()
        if not line:
            continue
        try:
            import json

            out.append({"raw": False, "data": json.loads(line)})
        except Exception:
            out.append({"raw": True, "data": {"line": line[:2000]}})
    out.reverse()
    return out

