from pathlib import Path
from typing import Any

import yaml

from eagle.models import Alert, ProcessEvent


class RuleEngine:
    def __init__(self, rules_path: Path) -> None:
        self.rules_path = rules_path
        self.rules: list[dict[str, Any]] = []
        self.reload()

    def reload(self) -> None:
        data = yaml.safe_load(self.rules_path.read_text(encoding="utf-8")) or {}
        self.rules = list(data.get("rules") or [])

    def evaluate(self, event: ProcessEvent) -> list[Alert]:
        alerts: list[Alert] = []
        for rule in self.rules:
            if self._matches(event, rule.get("match") or {}):
                alerts.append(
                    Alert(
                        rule_id=str(rule.get("id", "UNKNOWN")),
                        rule_name=str(rule.get("name", rule.get("id", "unknown"))),
                        severity=str(rule.get("severity", "medium")),
                        action=str(rule.get("action", "alert")),
                        process=event,
                        detail=self._detail(event, rule),
                    )
                )
        return alerts

    def _matches(self, event: ProcessEvent, match: dict[str, Any]) -> bool:
        name = (event.name or "").lower()
        parent = (event.parent_name or "").lower()
        cmdline = (event.cmdline or "").lower()
        exe = (event.exe or "").lower()
        tags = set(event.tags or [])

        if "process_name_in" in match:
            allowed = {x.lower() for x in match["process_name_in"]}
            if name not in allowed:
                return False

        if "process_name_not_in" in match:
            denied = {x.lower() for x in match["process_name_not_in"]}
            if name in denied:
                return False

        if "parent_name_in" in match:
            allowed = {x.lower() for x in match["parent_name_in"]}
            if parent not in allowed:
                return False

        if "parent_name_not_in" in match:
            denied = {x.lower() for x in match["parent_name_not_in"]}
            if parent in denied:
                return False

        if "cmdline_contains_any" in match:
            needles = [x.lower() for x in match["cmdline_contains_any"]]
            if not any(n in cmdline for n in needles):
                return False

        if "cmdline_contains_all" in match:
            needles = [x.lower() for x in match["cmdline_contains_all"]]
            if not all(n in cmdline for n in needles):
                return False

        if "path_contains_any" in match:
            needles = [x.lower() for x in match["path_contains_any"]]
            hay = exe or ""
            if not any(n in hay for n in needles):
                return False

        if "path_not_contains_any" in match:
            needles = [x.lower() for x in match["path_not_contains_any"]]
            hay = exe or ""
            if any(n in hay for n in needles):
                return False

        if "process_name_endswith" in match:
            suffixes = [x.lower() for x in match["process_name_endswith"]]
            if not any(name.endswith(s) for s in suffixes):
                return False

        if "tags_any" in match:
            wanted = set(match["tags_any"])
            if tags.isdisjoint(wanted):
                return False

        return True

    def _detail(self, event: ProcessEvent, rule: dict[str, Any]) -> str:
        return (
            f"rule={rule.get('id')} pid={event.pid} name={event.name} "
            f"parent={event.parent_name} exe={event.exe}"
        )

"""
Heurísticas leves de memória — protótipo.

Em produção: APIs nativas (ReadProcessMemory, VirtualQueryEx), ETW,
e drivers assinados. Aqui usamos apenas metadados acessíveis via psutil
para não introduzir código ofensivo nem PoCs de exploit.
"""

from __future__ import annotations

import psutil

from eagle.models import ProcessEvent


def annotate_memory_hints(events: list[ProcessEvent], sample_limit: int = 40) -> list[ProcessEvent]:
    """
    Marca processos com indicadores indiretos:
    - muitos threads + sem exe resolvido (possível reflective / hollowed)
    - memória RSS muito alta vs. peers do mesmo nome (outlier grosseiro)
    """
    skip_names = {"system", "idle", "registry", "memory compression", "system interrupts"}
    by_name: dict[str, list[tuple[int, int]]] = {}
    meta: dict[int, dict] = {}

    for i, event in enumerate(events):
        if i >= sample_limit:
            break
        if event.pid < 8 or (event.name or "").lower() in skip_names:
            continue
        try:
            p = psutil.Process(event.pid)
            with p.oneshot():
                mem = p.memory_info().rss
                threads = p.num_threads()
                exe = p.exe()
            meta[event.pid] = {"rss": mem, "threads": threads, "exe": exe}
            by_name.setdefault(event.name, []).append((event.pid, mem))
        except (psutil.Error, OSError):
            continue

    averages: dict[str, float] = {}
    for name, pairs in by_name.items():
        if not pairs:
            continue
        averages[name] = sum(m for _, m in pairs) / len(pairs)

    for event in events:
        if event.pid < 8 or (event.name or "").lower() in skip_names:
            continue
        info = meta.get(event.pid)
        if not info:
            continue
        tags = set(event.tags)
        exe = info.get("exe") or event.exe
        if not exe and info.get("threads", 0) >= 8:
            tags.add("memory_rwx")  # label de heurística (não prova RWX real)
        avg = averages.get(event.name)
        if avg and avg > 0 and info["rss"] > avg * 8 and info["rss"] > 200 * 1024 * 1024:
            tags.add("memory_rwx")
        event.tags = sorted(tags)

    return events

