import json
import shutil
from pathlib import Path

import psutil

from eagle.models import Alert


class Responder:
    def __init__(
        self,
        quarantine_dir: Path,
        alerts_log: Path,
        enforce: bool = False,
    ) -> None:
        self.quarantine_dir = quarantine_dir
        self.alerts_log = alerts_log
        self.enforce = enforce
        self.quarantine_dir.mkdir(parents=True, exist_ok=True)
        self.alerts_log.parent.mkdir(parents=True, exist_ok=True)

    def handle(self, alert: Alert) -> None:
        self._append_alert(alert)
        action = (alert.action or "alert").lower()

        if action in {"monitor", "alert"}:
            return

        if not self.enforce:
            return

        if action in {"kill", "block", "quarantine"}:
            self._kill(alert.process.pid)

        if action == "quarantine" and alert.process.exe:
            self._quarantine_file(alert.process.exe)

    def _append_alert(self, alert: Alert) -> None:
        with self.alerts_log.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(alert.to_dict(), ensure_ascii=False) + "\n")

    def _kill(self, pid: int) -> None:
        try:
            p = psutil.Process(pid)
            p.terminate()
        except (psutil.Error, OSError):
            return

    def _quarantine_file(self, path: str) -> None:
        src = Path(path)
        if not src.is_file():
            return
        dest = self.quarantine_dir / f"{src.stem}_{src.stat().st_mtime_ns}{src.suffix}.quarantine"
        try:
            shutil.move(str(src), str(dest))
        except OSError:
            return

