import time
from collections import defaultdict
from typing import Iterable

import psutil

from eagle.models import ProcessEvent


class Sensor:
    """Coleta telemetria de processos (polling). Produção usaria ETW/callbacks."""

    def __init__(self) -> None:
        self._seen: dict[int, float] = {}
        self._name_by_pid: dict[int, str] = {}
        self._write_hints: dict[int, int] = defaultdict(int)

    def snapshot_processes(self) -> list[ProcessEvent]:
        events: list[ProcessEvent] = []
        current_pids: set[int] = set()

        for proc in psutil.process_iter(
            ["pid", "ppid", "name", "exe", "cmdline", "username", "create_time"]
        ):
            try:
                info = proc.info
                pid = info["pid"]
                current_pids.add(pid)
                name = (info.get("name") or "").lower()
                self._name_by_pid[pid] = name

                cmdline_list = info.get("cmdline") or []
                cmdline = " ".join(cmdline_list) if cmdline_list else ""
                parent_name = self._name_by_pid.get(info.get("ppid") or -1)

                event = ProcessEvent(
                    pid=pid,
                    ppid=info.get("ppid") or 0,
                    name=name,
                    exe=info.get("exe"),
                    cmdline=cmdline,
                    username=info.get("username"),
                    create_time=info.get("create_time") or 0.0,
                    parent_name=parent_name,
                )
                events.append(event)
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                continue

        stale = [pid for pid in self._seen if pid not in current_pids]
        for pid in stale:
            self._seen.pop(pid, None)
            self._write_hints.pop(pid, None)

        return events

    def new_or_updated(self, events: Iterable[ProcessEvent]) -> list[ProcessEvent]:
        fresh: list[ProcessEvent] = []
        for event in events:
            prev = self._seen.get(event.pid)
            if prev is None or abs(prev - event.create_time) > 0.01:
                self._seen[event.pid] = event.create_time
                fresh.append(event)
        return fresh

    def note_file_write_activity(self, pid: int, count: int = 1) -> None:
        """Gancho para futuros hooks de filesystem; prototype usa incremento manual/teste."""
        self._write_hints[pid] += count

    def mass_write_pids(self, threshold: int = 50) -> set[int]:
        return {pid for pid, n in self._write_hints.items() if n >= threshold}


